package dao;

import database.DatabaseConnection;
import model.Agent;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Statement;
import java.util.ArrayList;
import java.util.List;

/**
 * Data Access Object for Agent entities.
 * Handles CRUD operations and analytical reporting queries.
 */
public class AgentDAO {

    /**
     * Inserts a new agent into the database.
     * If agent ID is generated by DB auto-increment, the generated ID is set back onto the agent object.
     *
     * @param agent the Agent object to add
     * @throws SQLException on database error
     */
    public void addAgent(Agent agent) throws SQLException {
        String sql = "INSERT INTO agents (agent_name, phone, email, agency_id) VALUES (?, ?, ?, ?)";
        Connection conn = DatabaseConnection.getConnection();
        if (conn == null) {
            throw new SQLException("Unable to obtain database connection.");
        }

        try (PreparedStatement stmt = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
            stmt.setString(1, agent.getAgentName());
            stmt.setString(2, agent.getPhone());
            stmt.setString(3, agent.getEmail());
            stmt.setInt(4, agent.getAgencyId());

            stmt.executeUpdate();

            try (ResultSet generatedKeys = stmt.getGeneratedKeys()) {
                if (generatedKeys.next()) {
                    agent.setAgentId(generatedKeys.getInt(1));
                }
            }
        }
    }

    /**
     * Updates an existing agent in the database.
     *
     * @param agent the Agent object containing updated values
     * @throws SQLException on database error
     */
    public void updateAgent(Agent agent) throws SQLException {
        String sql = "UPDATE agents SET agent_name = ?, phone = ?, email = ?, agency_id = ? WHERE agent_id = ?";
        Connection conn = DatabaseConnection.getConnection();
        if (conn == null) {
            throw new SQLException("Unable to obtain database connection.");
        }

        try (PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setString(1, agent.getAgentName());
            stmt.setString(2, agent.getPhone());
            stmt.setString(3, agent.getEmail());
            stmt.setInt(4, agent.getAgencyId());
            stmt.setInt(5, agent.getAgentId());

            stmt.executeUpdate();
        }
    }

    /**
     * Deletes an agent by ID.
     *
     * @param agentId the ID of the agent to delete
     * @throws SQLException on database error
     */
    public void deleteAgent(int agentId) throws SQLException {
        String sql = "DELETE FROM agents WHERE agent_id = ?";
        Connection conn = DatabaseConnection.getConnection();
        if (conn == null) {
            throw new SQLException("Unable to obtain database connection.");
        }

        try (PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setInt(1, agentId);
            stmt.executeUpdate();
        }
    }

    /**
     * Retrieves an agent by ID.
     *
     * @param agentId the ID of the agent
     * @return the Agent if found, or null otherwise
     * @throws SQLException on database error
     */
    public Agent getAgentById(int agentId) throws SQLException {
        String sql = "SELECT agent_id, agent_name, phone, email, agency_id FROM agents WHERE agent_id = ?";
        Connection conn = DatabaseConnection.getConnection();
        if (conn == null) {
            throw new SQLException("Unable to obtain database connection.");
        }

        try (PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setInt(1, agentId);

            try (ResultSet rs = stmt.executeQuery()) {
                if (rs.next()) {
                    return mapResultSetToAgent(rs);
                }
            }
        }
        return null;
    }

    /**
     * Searches for agents by matching name pattern (case-insensitive substring).
     *
     * @param name substring or search keyword
     * @return list of matching Agent objects
     * @throws SQLException on database error
     */
    public List<Agent> searchAgentsByName(String name) throws SQLException {
        List<Agent> agents = new ArrayList<>();
        String sql = "SELECT agent_id, agent_name, phone, email, agency_id FROM agents WHERE agent_name LIKE ?";
        Connection conn = DatabaseConnection.getConnection();
        if (conn == null) {
            throw new SQLException("Unable to obtain database connection.");
        }

        try (PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setString(1, "%" + name + "%");

            try (ResultSet rs = stmt.executeQuery()) {
                while (rs.next()) {
                    agents.add(mapResultSetToAgent(rs));
                }
            }
        }
        return agents;
    }

    /**
     * Retrieves all agents ordered by agent_id.
     *
     * @return list of all Agent objects
     * @throws SQLException on database error
     */
    public List<Agent> getAllAgents() throws SQLException {
        List<Agent> agents = new ArrayList<>();
        String sql = "SELECT agent_id, agent_name, phone, email, agency_id FROM agents ORDER BY agent_id ASC";
        Connection conn = DatabaseConnection.getConnection();
        if (conn == null) {
            throw new SQLException("Unable to obtain database connection.");
        }

        try (PreparedStatement stmt = conn.prepareStatement(sql);
             ResultSet rs = stmt.executeQuery()) {
            while (rs.next()) {
                agents.add(mapResultSetToAgent(rs));
            }
        }
        return agents;
    }

    /**
     * Counts the total number of agents registered.
     *
     * @return total count
     * @throws SQLException on database error
     */
    public int getTotalAgents() throws SQLException {
        String sql = "SELECT COUNT(*) FROM agents";
        Connection conn = DatabaseConnection.getConnection();
        if (conn == null) {
            throw new SQLException("Unable to obtain database connection.");
        }

        try (PreparedStatement stmt = conn.prepareStatement(sql);
             ResultSet rs = stmt.executeQuery()) {
            if (rs.next()) {
                return rs.getInt(1);
            }
        }
        return 0;
    }

    /**
     * Checks if an agent exists with the given ID.
     *
     * @param agentId the ID to verify
     * @return true if exists, false otherwise
     * @throws SQLException on database error
     */
    public boolean agentExists(int agentId) throws SQLException {
        String sql = "SELECT 1 FROM agents WHERE agent_id = ?";
        Connection conn = DatabaseConnection.getConnection();
        if (conn == null) {
            throw new SQLException("Unable to obtain database connection.");
        }

        try (PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setInt(1, agentId);
            try (ResultSet rs = stmt.executeQuery()) {
                return rs.next();
            }
        }
    }

    /**
     * Returns agents who have at least one mandate (JOIN query).
     * Returns {agentId, agentName, phone, email, agencyId, mandateId, mandateType}.
     *
     * @return list of Object arrays representing joined records
     * @throws SQLException on database error
     */
    public List<Object[]> getAgentsWithMandates() throws SQLException {
        List<Object[]> results = new ArrayList<>();
        String sql = "SELECT DISTINCT a.agent_id, a.agent_name, a.phone, a.email, a.agency_id, m.mandate_id, m.mandate_type " +
                     "FROM agents a " +
                     "JOIN mandates m ON a.agent_id = m.agent_id " +
                     "ORDER BY a.agent_id, m.mandate_id";
        Connection conn = DatabaseConnection.getConnection();
        if (conn == null) {
            throw new SQLException("Unable to obtain database connection.");
        }

        try (PreparedStatement stmt = conn.prepareStatement(sql);
             ResultSet rs = stmt.executeQuery()) {
            while (rs.next()) {
                results.add(new Object[]{
                    rs.getInt("agent_id"),
                    rs.getString("agent_name"),
                    rs.getString("phone"),
                    rs.getString("email"),
                    rs.getInt("agency_id"),
                    rs.getInt("mandate_id"),
                    rs.getString("mandate_type")
                });
            }
        }
        return results;
    }

    /**
     * Returns {agentName, mandateCount} for the agent handling the maximum mandates.
     *
     * @return Object array containing [agentName, mandateCount], or null if no mandates exist
     * @throws SQLException on database error
     */
    public Object[] getAgentWithMaxMandates() throws SQLException {
        String sql = "SELECT a.agent_name, COUNT(m.mandate_id) AS mandate_count " +
                     "FROM agents a " +
                     "JOIN mandates m ON a.agent_id = m.agent_id " +
                     "GROUP BY a.agent_id, a.agent_name " +
                     "ORDER BY mandate_count DESC " +
                     "LIMIT 1";
        Connection conn = DatabaseConnection.getConnection();
        if (conn == null) {
            throw new SQLException("Unable to obtain database connection.");
        }

        try (PreparedStatement stmt = conn.prepareStatement(sql);
             ResultSet rs = stmt.executeQuery()) {
            if (rs.next()) {
                return new Object[]{
                    rs.getString("agent_name"),
                    rs.getInt("mandate_count")
                };
            }
        }
        return null;
    }

    /**
     * Returns {agentId, agentName, mandateCount} for each agent.
     * Includes agents even if they have 0 mandates (using LEFT JOIN).
     *
     * @return list of Object arrays with agent details and mandate counts
     * @throws SQLException on database error
     */
    public List<Object[]> getMandateCountPerAgent() throws SQLException {
        List<Object[]> results = new ArrayList<>();
        String sql = "SELECT a.agent_id, a.agent_name, COUNT(m.mandate_id) AS mandate_count " +
                     "FROM agents a " +
                     "LEFT JOIN mandates m ON a.agent_id = m.agent_id " +
                     "GROUP BY a.agent_id, a.agent_name " +
                     "ORDER BY mandate_count DESC, a.agent_id ASC";
        Connection conn = DatabaseConnection.getConnection();
        if (conn == null) {
            throw new SQLException("Unable to obtain database connection.");
        }

        try (PreparedStatement stmt = conn.prepareStatement(sql);
             ResultSet rs = stmt.executeQuery()) {
            while (rs.next()) {
                results.add(new Object[]{
                    rs.getInt("agent_id"),
                    rs.getString("agent_name"),
                    rs.getInt("mandate_count")
                });
            }
        }
        return results;
    }

    /**
     * Maps the current row of a ResultSet to an Agent instance.
     *
     * @param rs ResultSet positioned at current row
     * @return Agent object
     * @throws SQLException on retrieval error
     */
    private Agent mapResultSetToAgent(ResultSet rs) throws SQLException {
        return new Agent(
            rs.getInt("agent_id"),
            rs.getString("agent_name"),
            rs.getString("phone"),
            rs.getString("email"),
            rs.getInt("agency_id")
        );
    }
}
